#!/usr/bin/env bash
# LightDM X11 session for the kiosk user.
# Openbox alone does not start ~/.config/autostart/*.desktop files, so we
# launch the kiosk from Openbox's own autostart file.
set -Eeuo pipefail

INSTALL_DIR="/opt/pi-screen"
OPENBOX_DIR="${HOME}/.config/openbox"
mkdir -p "$OPENBOX_DIR"

# Keep this file in sync with the install, so a repo update takes effect after
# the next LightDM restart without re-running the whole bootstrap.
cat > "${OPENBOX_DIR}/autostart" <<'AUTOSTART'
# Generated by /opt/pi-screen/kiosk/x11-session.sh
xset s off -dpms s noblank >/dev/null 2>&1 || true
/opt/pi-screen/kiosk/start-kiosk.sh &
AUTOSTART
chmod 0755 "${OPENBOX_DIR}/autostart"

exec openbox-session
